package main

import (
	"fmt"
	"github.com/atotto/clipboard"
	"strings"
)

func addSpace(str string) string {
	var result strings.Builder

	for i, ch := range str {
		if i > 0 && i%2 == 0 {
			result.WriteString(" ")
		}
		result.WriteRune(ch)
	}

	return result.String()
}

func main() {
	input := ""
	output := addSpace(input)

	err := clipboard.WriteAll(output)
	if err != nil {
		fmt.Println("Failed to copy to clipboard:", err)
	} else {
		fmt.Println("Copied to clipboard:", output)
	}
}
